-- Runs every gold load procedure: dimensions first, then the
-- tables that read them. For manual reloads; the daily job runs
-- one task per procedure.
-- Generated by `python -m dbde render` from every gold spec. Do not edit: change the spec and render again.

CREATE OR REPLACE PROCEDURE ${gold_catalog}.ops.RunGoldLoads(
    RunLoadDate DATE,
    RunLoadStepID STRING
)
LANGUAGE SQL
SQL SECURITY INVOKER
COMMENT 'Runs every gold load procedure in order. Generated by dbde.'
AS BEGIN
    CALL ${gold_catalog}.distribution.LoadDimAgent(RunLoadDate, RunLoadStepID);
    CALL ${gold_catalog}.sales.LoadFactNewBusiness(RunLoadDate, RunLoadStepID);
END;
-- GO
